-- Hosted food images from Pexels (free stock photos)
-- Re-runnable: overwrites existing image_url values

UPDATE public.categories SET image_url = CASE name_en
  WHEN 'Fish' THEN 'https://images.pexels.com/photos/2132007/pexels-photo-2132007.jpeg?auto=compress&cs=tinysrgb&w=600&h=400&fit=crop'
