  WHEN 'Trays' THEN 'https://images.pexels.com/photos/566345/pexels-photo-566345.jpeg?auto=compress&cs=tinysrgb&w=600&h=400&fit=crop'
  WHEN 'Soup' THEN 'https://images.pexels.com/photos/4518846/pexels-photo-4518846.jpeg?auto=compress&cs=tinysrgb&w=600&h=400&fit=crop'
